import React, { useState } from 'react';
import axios from 'axios';
import { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router';
import { Link } from 'react-router-dom';


function UserProfile() {
    const [user, setUser] = useState(null);
    const [Loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        //get user id from local storage
        const userId = localStorage.getItem('userId');
        if (!userId) {
            setError('No user logged in');
            setLoading(false);
            return;
        }

        //fetch user profile from backend
        axios.get(`http://localhost:8080/user/${userId}`)
            .then(response => {
                setUser(response.data);
                setLoading(false);
            })
            .catch(err => {
                setError('Error fetching user profile');
                setLoading(false);
            });
    }, []);
    
    const UpdateNavigate = (id) => {
        window.location.href = `/updateprofile/${id}`;
    }

    //delete function
    const deleteAccount = async () => {
        //display confirmation dialog
        const confirmation =
        window.confirm('Are you sure you want to delete this account ? ');
        if (confirmation){
            try{
                //send delete request
                await axios.delete(`http://localhost:8080/user/${user.id}`);
                //success alert
                alert('Account deleted successfully');
                localStorage.removeItem('userId');//remove user id from local storage
                window.location.href = '/register';//redirect to register page
            }catch(error){
                alert('Error deleting account:', error);
            }
        }
    }
    
    if (Loading) return (
        <div style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
        }}>
            <p style={{ color: 'white', fontSize: '18px' }}>Loading...</p>
        </div>
    );
    
    if (error) return (
        <div style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
        }}>
            <div style={{
                background: 'white',
                padding: '30px',
                borderRadius: '15px',
                boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
                textAlign: 'center'
            }}>
                <p style={{ color: '#e74c3c', fontSize: '16px', margin: 0 }}>{error}</p>
                <a href="/login" style={{
                    display: 'inline-block',
                    marginTop: '20px',
                    padding: '10px 20px',
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: 'white',
                    textDecoration: 'none',
                    borderRadius: '8px',
                    fontWeight: '600'
                }}>
                    Go to Login
                </a>
            </div>
        </div>
    );
    
    return (
        <div style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            padding: '20px'
        }}>
            <div style={{
                background: 'white',
                padding: '40px',
                borderRadius: '15px',
                boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
                width: '100%',
                maxWidth: '500px'
            }}>
                <div style={{ textAlign: 'center', marginBottom: '30px' }}>
                    <div style={{
                        width: '80px',
                        height: '80px',
                        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        margin: '0 auto 20px',
                        fontSize: '40px'
                    }}>
                        👤
                    </div>
                    <h2 style={{
                        fontSize: '26px',
                        color: '#333',
                        margin: '0',
                        fontWeight: '600'
                    }}>User Profile</h2>
                </div>

                {user ? (
                    <div>
                        <div style={{
                            background: '#f8f9fa',
                            padding: '20px',
                            borderRadius: '10px',
                            marginBottom: '25px'
                        }}>
                            <div style={{ marginBottom: '15px' }}>
                                <label style={{
                                    display: 'block',
                                    fontSize: '12px',
                                    color: '#666',
                                    marginBottom: '5px',
                                    fontWeight: '500',
                                    textTransform: 'uppercase'
                                }}>Full Name</label>
                                <p style={{
                                    margin: 0,
                                    fontSize: '16px',
                                    color: '#333',
                                    fontWeight: '500'
                                }}>👤 {user.fullname}</p>
                            </div>

                            <div style={{ marginBottom: '15px' }}>
                                <label style={{
                                    display: 'block',
                                    fontSize: '12px',
                                    color: '#666',
                                    marginBottom: '5px',
                                    fontWeight: '500',
                                    textTransform: 'uppercase'
                                }}>Email</label>
                                <p style={{
                                    margin: 0,
                                    fontSize: '16px',
                                    color: '#333',
                                    fontWeight: '500'
                                }}>📧 {user.email}</p>
                            </div>

                            <div style={{ marginBottom: '15px' }}>
                                <label style={{
                                    display: 'block',
                                    fontSize: '12px',
                                    color: '#666',
                                    marginBottom: '5px',
                                    fontWeight: '500',
                                    textTransform: 'uppercase'
                                }}>Password</label>
                                <p style={{
                                    margin: 0,
                                    fontSize: '16px',
                                    color: '#333',
                                    fontWeight: '500'
                                }}>🔒 {user.password}</p>
                            </div>

                            <div>
                                <label style={{
                                    display: 'block',
                                    fontSize: '12px',
                                    color: '#666',
                                    marginBottom: '5px',
                                    fontWeight: '500',
                                    textTransform: 'uppercase'
                                }}>Phone</label>
                                <p style={{
                                    margin: 0,
                                    fontSize: '16px',
                                    color: '#333',
                                    fontWeight: '500'
                                }}>📱 {user.phone || 'Not provided'}</p>
                            </div>
                        </div>

                        <div style={{ display: 'flex', gap: '10px' }}>
                            <button 
                                onClick={() => UpdateNavigate(user.id)}
                                style={{
                                    flex: 1,
                                    padding: '14px',
                                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '8px',
                                    fontSize: '15px',
                                    fontWeight: '600',
                                    cursor: 'pointer',
                                    transition: 'all 0.3s',
                                    boxShadow: '0 4px 15px rgba(102, 126, 234, 0.4)'
                                }}
                                onMouseOver={(e) => {
                                    e.currentTarget.style.transform = 'translateY(-2px)';
                                    e.currentTarget.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.6)';
                                }}
                                onMouseOut={(e) => {
                                    e.currentTarget.style.transform = 'translateY(0)';
                                    e.currentTarget.style.boxShadow = '0 4px 15px rgba(102, 126, 234, 0.4)';
                                }}
                            >
                                ✏️ Update Profile
                            </button>

                            <button 
                                onClick={() => deleteAccount()}
                                style={{
                                    flex: 1,
                                    padding: '14px',
                                    background: 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '8px',
                                    fontSize: '15px',
                                    fontWeight: '600',
                                    cursor: 'pointer',
                                    transition: 'all 0.3s',
                                    boxShadow: '0 4px 15px rgba(231, 76, 60, 0.4)'
                                }}
                                onMouseOver={(e) => {
                                    e.currentTarget.style.transform = 'translateY(-2px)';
                                    e.currentTarget.style.boxShadow = '0 6px 20px rgba(231, 76, 60, 0.6)';
                                }}
                                onMouseOut={(e) => {
                                    e.currentTarget.style.transform = 'translateY(0)';
                                    e.currentTarget.style.boxShadow = '0 4px 15px rgba(231, 76, 60, 0.4)';
                                }}
                            >
                                🗑️ Delete Account
                            </button>
                        </div>
                    </div>
                ) : (
                    <p style={{ textAlign: 'center', color: '#666' }}>No User Found</p>
                )}
            </div>
        </div>
    );
}

export default UserProfile
